const restoreInvestigacao = `-- name: RestoreInvestigacao :execrows
UPDATE investigacoes SET deleted_at = NULL, deleted_by = NULL WHERE id = $1 AND deleted_at IS NOT NULL
`

func (q *Queries) RestoreInvestigacao(ctx context.Context, id int64) (int64, error) {
	result, err := q.db.Exec(ctx, restoreInvestigacao, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

